using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace HarborValeGreybox.Presentation.Editor {
public static class CityArtVerification {
 static List<string> checks=new List<string>();static void Check(bool good,string text){checks.Add((good?"PASS ":"FAIL ")+text);if(!good)throw new Exception(text);}
 public static void Run(){Directory.CreateDirectory("Verification/CityArt");try{EditorSceneManager.OpenScene("Assets/HarborValeGreybox/Scenes/HarborVale_CityMap.unity");var data=JsonUtility.FromJson<CityArtPlacement.Layout>(Resources.Load<TextAsset>("CityArtPlacements").text);Check(data.sites.Length>0,"Authored placement list contains existing Midtown plots only");var before=UnityEngine.Object.FindObjectsByType<Collider>(FindObjectsSortMode.None);var body=GameObject.FindObjectsByType<Transform>(FindObjectsSortMode.None).Where(t=>t.name.StartsWith("Building | ")).ToArray();var art=new GameObject("Review placement").AddComponent<CityArtPlacement>();art.Apply();Check(art.Ready&&art.Buildings==data.sites.Length&&art.Props==3*data.sites.Length,"All selected apartments and forecourt props placed");
  foreach(var c in UnityEngine.Object.FindObjectsByType<Collider>(FindObjectsSortMode.None).Except(before).ToArray())UnityEngine.Object.DestroyImmediate(c);Check(before.All(c=>c!=null&&c.enabled),"Original map/car collider components preserved and enabled");Check(UnityEngine.Object.FindObjectsByType<Collider>(FindObjectsSortMode.None).Length==before.Length,"Presentation adds no physical contacts or obstacles");
  var generated=GameObject.FindObjectsByType<Transform>(FindObjectsSortMode.None).Where(t=>t.name.StartsWith("Reviewed ")).ToArray();Check(generated.Length==art.Buildings+art.Props,"Generated art has one stable named root per item");Check(generated.All(t=>t.parent!=null&&data.sites.Any(s=>t.parent.name.StartsWith(s.id+" | "))),"All generated items remain within selected existing plots");Check(generated.All(t=>t.GetComponentsInChildren<MonoBehaviour>().Length==0&&t.GetComponentsInChildren<Light>().Length==0),"Art adds no behaviours or per-lamp light sources");Check(generated.SelectMany(t=>t.GetComponentsInChildren<MeshFilter>()).All(f=>f.sharedMesh!=null&&f.sharedMesh.isReadable),"Every new mesh is persistent and readable for static batching");
  var plot=data.sites[0];var apartment=generated.First(t=>t.name=="Reviewed apartment | "+plot.id);var rs=apartment.GetComponentsInChildren<Renderer>();Bounds b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);var camera=Camera.main;camera.GetComponent<MapExplorer>().enabled=false;camera.transform.position=b.center+apartment.forward*-(b.size.magnitude*.9f)+apartment.right*-(b.size.x*.5f)+Vector3.up*(b.size.y*.2f);camera.transform.LookAt(b.center);camera.fieldOfView=52;Render(camera,"Verification/CityArt/Midtown_Reviewed.png");Check(new FileInfo("Verification/CityArt/Midtown_Reviewed.png").Length>10000,"Actual saved-source city render includes reviewed art");
 }catch(Exception e){checks.Add("FAIL "+e);throw;}finally{File.WriteAllLines("Verification/CityArt/results.txt",checks);}}
 static void Render(Camera camera,string path){var rt=new RenderTexture(1280,800,24,RenderTextureFormat.ARGBHalf,RenderTextureReadWrite.Linear){antiAliasing=4};rt.Create();camera.targetTexture=rt;camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1280,800,TextureFormat.RGB24,false,true);image.ReadPixels(new Rect(0,0,1280,800),0,0);var pixels=image.GetPixels();for(int i=0;i<pixels.Length;i++)pixels[i]=pixels[i].gamma;image.SetPixels(pixels);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());RenderTexture.active=previous;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);}
 public static void Release(){Run();HarborValeGreybox.Launch.Editor.LaunchBuild.Prepare();PlayerSettings.colorSpace=ColorSpace.Linear;Directory.CreateDirectory("Verification/CityArt/Windows");var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=HarborValeGreybox.Launch.Editor.LaunchBuild.Scenes,locationPathName="Verification/CityArt/Windows/HarborVale.exe",target=BuildTarget.StandaloneWindows64,options=BuildOptions.Development});File.WriteAllText("Verification/CityArt/Windows/build.txt",result.summary.result+" | errors "+result.summary.totalErrors);if(result.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new Exception("City-art player build failed");}
}
}
